from pathlib import Path
import re

p=Path('report_human_datasets.md')
lines=p.read_text(encoding='utf-8').splitlines()

def replace_line(start, body, keep_citations=False, keep_heading=False, tail=None):
    matches=[i for i,x in enumerate(lines) if x.startswith(start)]
    assert len(matches)==1, (start,matches)
    i=matches[0]
    old=lines[i]
    prefix=''
    if keep_heading:
        m=re.match(r'\*\*\[.*?\]\(.*?\)\.?\*\*',old)
        assert m,old
        prefix=m.group()+' '
    suffix=''
    if tail:
        suffix=' '+old[old.index(tail):]
    elif keep_citations:
        k=old.rfind(' ([')
        assert k>=0,old
        suffix=old[k:]
    lines[i]=prefix+body+suffix

